import java.util.*;

class Solution {
    public int findAbsent(int[] nums) {
        int x = nums.length;                   // the value n is never an index, so start with it
        for (int i = 0; i < nums.length; i++) {
            x ^= i ^ nums[i];                  // present numbers cancel in pairs
        }
        return x;
    }
}

